-- Wedstrijden op Sportpark De Schuytgraaf, 2026-11-13 t/m 2026-11-29 (bron: voetbal.nl accommodatieprogramma, opgehaald 13-11-2026)
-- Vervangt eerder ingelezen voetbal.nl-wedstrijden vanaf de eerste datum; wedstrijden die in de tool zijn aangemaakt blijven staan.
alter table public.cap_matches drop constraint if exists cap_matches_kwart;
alter table public.cap_matches add constraint cap_matches_kwart check (cardinality(units) between 0 and 12);
begin;
delete from public.cap_matches where bron = 'voetbal.nl' and datum >= '2026-11-13';
commit;
select datum, count(*) as wedstrijden, count(*) filter (where cardinality(units)=0) as zonder_veld from public.cap_matches where datum >= '2026-11-13' group by datum order by datum;
